    "renciRole": "RENCI is responsible for all aspects of the project with Matt Satusky as PI.",
    "webDescription": "NHLBI has targeted AI image analysis as a key area for expansion in the BioData Catalyst ecosystem. However, there are currently limited to no resources available for researchers to estimate cloud costs when submitting proposals. RENCI will perform cloud cost analysis for common AI imaging applications on the BioData Catalyst powered by Seven Bridges and MIDRC platforms using publicly accessible datasets.",
