    "webUrl": null,
    "slug": "aerpaw",
    "renciRole": "RENCI is responsible for developing a portal with the control framework software for this testbed.",
    "webDescription": "Aerial Experimentation Research Platform for Advanced Wireless [AERPAW](https://aerpaw.org/) is a $24 million grant awarded by the National Science Foundation to develop an advanced wireless research platform, led by North Carolina State University, in partnership with Wireless Research Center of North Carolina, Mississippi State University and Renaissance Computing Institute (RENCI) at the University of North Carolina at Chapel Hill; additional partners include Town of Cary, City of Raleigh, North Carolina Department of Transportation, Purdue University, University of South Carolina, and many other academic, industry and municipal partners. AERPAW, the nation’s first aerial wireless experimentation platform spanning 5G technologies and beyond, will enable cutting-edge research — with the potential to create transformative wireless advances for aerial systems.",
